import React from 'react';
import { Link } from 'react-router-dom';

function formatPrice(price) {
    // Chuyển 479000 thành 479.000
    return new Intl.NumberFormat('vi-VN').format(price) + '₫';
}

function ProductCard({ data }) {
    const { id, title, price, imageUrl, link = `/products/${id}` } = data;
    const numericPrice = price || 0;

    return (
        <div className="product-item">
            <div className="inner-image">
                <Link to={link}>
                    <img src={`/assets/images/${imageUrl}`} alt={title} />
                </Link>
            </div>
            <div className="inner-content">
                <h3 className="inner-title">
                    <Link to={link}>{title}</Link>
                </h3>
                <div className="inner-price">{formatPrice(numericPrice)}</div>
            </div>
        </div>
    );
}

export default ProductCard;
